'use strict';
// Geometry and movement modifiers apply to both new fighters and cursed opponents.
function unitScale(u){const permanent=u.type===11?Math.max(.4,Math.pow(.94,u.dolphinStacks??0)):u.type===12?Math.min(2.4,1+(u.predatorStacks??0)*.04):1;return permanent*(u.towerBodyScale??1)*(u.curseTime>0?.65:1);}
function scaleAround(point,scale){if(scale===1)return;ctx.translate(point.x,point.y);ctx.scale(scale,scale);ctx.translate(-point.x,-point.y);}
function novelMovementRate(u){return u.type===10?1+(u.guardStacks??0)*.15:u.type===11?Math.min(2,1+(u.dolphinStacks??0)*.04):1;}
function novelLocked(u){return u.type===10&&u.guardRemaining>0;}
function novelStatus(u){if(u.puppetControl)return '조종 · '+u.puppetControl.remaining.toFixed(1)+'초';if(u.type===25)return '붉은 실 · '+puppetLinkedAllies(u).length+'명 연결';if(u.type===24)return u.frogAction?(u.frogAction.rescue?'아군 구출 중':'꿀꺽 · 머금는 중'):u.frogHop?'폴짝':'혀로 HP가 많은 적 포획';if(u.type===23)return machineGunStatus(u);if(u.hp<=0)return '전투 불능';if(u.type===21)return u.mirrorReflectTime>0?'반사 '+u.mirrorReflectTime.toFixed(1)+'초':'광원 · 4회 도탄';if(u.type===19)return fanaticSaint(u)?'성자 #'+u.saintId+' · 신앙':u.saintFallen?'광분 · 공격·공속 +30%':'성자 없음 · 돌격';if(u.type===20)return '연쇄 충격 · 감전 4중첩 기절';if(u.type===17)return u.heroRescue?'영웅등장 · 구출 돌진':u.heroRescueUsed?'영웅등장 사용 완료':'영웅등장 준비';if(u.type===18)return u.tankFlameReady?'다음 포탄 · 화염포':'느린 포격 · 후방 취약';if(u.type===13)return u.bomberRush?u.bomberFuse!=null?'자폭 점화 중':'HP 20% · 최후의 돌진':'2초 도화선 · 범위 폭발';if(duelLocked(u))return '가위바위보 진행 중';if(u.type===12)return '강화 비늘 '+(u.predatorStacks??0)+'중첩 · 크기 '+Math.round(unitScale(u)*100)+'%';if(u.type===10)return u.guardRemaining>0?'방어태세 '+u.guardRemaining.toFixed(1)+'초 · '+u.guardStacks+'중첩':u.lostSword?'특대검 회수 중':u.guardStacks?'다음 공격 +'+Math.round(u.guardStacks*6)+'% · 이동 +'+Math.round(u.guardStacks*15)+'%':'특대검 준비';return '크기 '+Math.round(unitScale(u)*100)+'% · 이동 +'+Math.round((novelMovementRate(u)-1)*100)+'%';}
function onNovelDamage(u,actual,{parryRecoil=false}={}){onChampionDamage(u,actual);if(u.type===13&&u.hp>0&&u.hp<=u.maxHp*.2)u.bomberRush=true;if(u.type===11){u.damageTakenTotal=(u.damageTakenTotal??0)+actual;u.dolphinStacks=Math.max(u.dolphinStacks??0,Math.floor((u.damageTakenTotal+1e-7)/(u.maxHp*.1)));}if(u.type!==10||u.hp<=0||u.stun>0||parryRecoil)return;if(u.guardRemaining>0){u.guardStacks++;return;}if(u.guardReady!==false){u.guardRemaining=4;u.guardReady=false;u.guardStacks=(u.guardStacks??0)+1;u.guardAnchor={x:u.x,y:u.y};u.attack=null;u.ultCast=null;u.kx=u.ky=u.vx=u.vy=u.headingX=u.headingY=0;u.action='방어태세';fx('shield',u.x,u.y,u.color,.24,{r:70,angle:u.face});addLog(`${u.name} · 4초 방어태세`);}}
function enforceNovelAnchors(){for(const u of alive())if(novelLocked(u)&&u.guardAnchor){u.x=u.guardAnchor.x;u.y=u.guardAnchor.y;u.kx=u.ky=u.vx=u.vy=0;}}
function advanceNovelTimers(dt){for(const u of alive()){u.curseTime=Math.max(0,(u.curseTime??0)-dt);u.guardRemaining=Math.max(0,(u.guardRemaining??0)-dt);if(u.type!==10||!u.lostSword)continue;const sword=u.lostSword;if(sword.flight>0){const step=Math.min(dt,sword.flight);sword.x=clamp(sword.x+sword.vx*step,35,765);sword.y=clamp(sword.y+sword.vy*step,35,765);sword.flight=Math.max(0,sword.flight-dt);sword.rotation+=step*13;}if(sword.flight<=0&&u.stun<=0&&!novelLocked(u)&&!duelLocked(u)&&dist(u,sword)<34){u.pickupTime+=dt;if(u.pickupTime>=.25){u.lostSword=null;u.pickupTime=0;u.cooldown=Math.min(u.cooldown,.3);u.action='특대검 회수';burst(u.x,u.y,u.color,20,140,.8,u.face);addLog(`${u.name} · 특대검 회수`);}}else u.pickupTime=0;}}
function applyShrinkCurse(target,source){if(target.hp<=0||target.invincible>0)return;target.curseTime=6;fx('curseMark',target.x,target.y,'#a8e6f1',.5,{unitId:target.id,r:60});burst(target.x,target.y,'#c2faff',26,230,Math.PI*2,0,'mote');addLog(`${source.name} · ${target.name} 축소 저주`);}
function moveNovel(u,target,enemies,allies,dt){if(u.type===10&&u.lostSword){if(novelLocked(u))return;const item=u.lostSword,d=dist(u,item)||1;let mx=(item.x-u.x)/d,my=(item.y-u.y)/d;const incoming=projectileThreat(u);if(incoming&&d>85){mx-=incoming.p.vy/(Math.hypot(incoming.p.vx,incoming.p.vy)||1)*u.ai.side*.4;my+=incoming.p.vx/(Math.hypot(incoming.p.vx,incoming.p.vy)||1)*u.ai.side*.4;}u.action='놓친 특대검을 주우러 이동';steerArchetype(u,mx,my,dt,novelMovementRate(u));return;}if(u.type!==11||u.attack?.kind==='headbutt')return;const b=u.ai;b.wanderClock=(b.wanderClock??0)-dt;if(!b.wanderGoal||b.wanderClock<=0||dist(u,b.wanderGoal)<45){b.wanderGoal={x:random(70,730),y:random(70,730)};b.wanderClock=random(.55,1.35);b.side=Math.random()<.5?-1:1;}let point=b.wanderGoal;if(target&&((dist(u,target)<235&&u.cooldown<.4)||elapsed<b.commitUntil)){point={x:target.x+target.vx*.2,y:target.y+target.vy*.2};}const d=dist(u,point)||1,dx=(point.x-u.x)/d,dy=(point.y-u.y)/d,sway=Math.sin(elapsed*5+b.phase)*.3;let mx=dx-dy*sway,my=dy+dx*sway;const incoming=projectileThreat(u);if(incoming&&!u.attack){const n=Math.hypot(incoming.p.vx,incoming.p.vy)||1;mx=mx*.5-incoming.p.vy/n*b.side*.65;my=my*.5+incoming.p.vx/n*b.side*.65;}u.action='방황 · 이리저리 뛰어다님';steerArchetype(u,mx,my,dt,novelMovementRate(u));}
function releaseGreatSword(u,a){u.guardReady=true;if(Math.random()<.15){const angle=random(-Math.PI,Math.PI);u.lostSword={x:u.x,y:u.y,vx:Math.cos(angle)*480,vy:Math.sin(angle)*480,flight:.6,rotation:angle,sizeBoost:a.sizeBoost??1,scale:unitScale(u)};u.pickupTime=0;u.action='특대검을 놓침';burst(u.x,u.y,u.color,24,230,1.2,angle);addLog(`${u.name} · 특대검을 놓쳐 회수 시작`);return;}spawnMeleeStrike(u,a,u.dmg*(a.damageBoost??1));fx('sweep',u.x,u.y,u.color,.16,{angle:a.angle,r:a.profile.reach*unitScale(u)*(a.sizeBoost??1),unitId:u.id});u.kx+=Math.cos(a.angle)*140;u.ky+=Math.sin(a.angle)*140;impactPause(3,a.angle);burst(u.x+Math.cos(a.angle)*100,u.y+Math.sin(a.angle)*100,'#ead5af',35,260,.7,a.angle);}
function startHeadbutt(u,target,ultimate=false){if(u.hp<=0||u.attack||u.stun>0||duelLocked(u)||!ultimate&&u.ultCast)return false;if(!ultimate){target=alive().filter(v=>v.faction!==u.faction&&canPerceive(u,v)).sort((a,b)=>dist(u,a)-dist(u,b))[0];if(!target||dist(u,target)>190*unitScale(u))return false;}if(!target||target.hp<=0||!canPerceive(u,target))return false;const profile={...ATTACK_PROFILES[11],windup:ultimate?.14:ATTACK_PROFILES[11].windup,active:ultimate?clamp(dist(u,target)/780+.12,.28,1.2):.32,recovery:ultimate?.12:.32};u.attack={kind:'headbutt',ultimate,targetId:target.id,phase:'windup',t:0,angle:Math.atan2(target.y-u.y,target.x-u.x),profile,serial:++u.attackSerial,hiddenLaunch:false,landed:false};consumeAttackIntent(u);u.cooldown=ultimate?.4:u.cd+random(.15,.35);u.face=u.attack.angle;u.revealTime=3;u.action='박치기 준비';return true;}
function advanceHeadbutt(u,dt){const a=u.attack;if(!a||a.kind!=='headbutt')return;if(u.hp<=0||u.stun>0){u.attack=null;return;}a.t+=dt;const target=units.find(v=>v.id===a.targetId&&v.hp>0);if(a.phase==='windup'){u.vx=u.vy=u.headingX=u.headingY=0;if(target&&canPerceive(u,target))a.angle=Math.atan2(target.y-u.y,target.x-u.x);u.face=a.angle;if(a.t>=a.profile.windup){a.phase='active';a.t=0;const s=spawnMeleeStrike(u,{...a,profile:{...a.profile,reach:64,cone:.18}},u.dmg*(a.ultimate?1.15:1));s.headbutt=true;u.ai.lastAttack=elapsed;u.kx=u.ky=0;}}
else if(a.phase==='active'){if(!a.landed){const vx=Math.cos(a.angle)*(a.ultimate?780:560)*novelMovementRate(u),vy=Math.sin(a.angle)*(a.ultimate?780:560)*novelMovementRate(u),from={x:u.x,y:u.y};u.x=clamp(u.x+vx*dt,28,772);u.y=clamp(u.y+vy*dt,28,772);u.vx=(u.x-from.x)/dt;u.vy=(u.y-from.y)/dt;u.face=a.angle;u.action='축소 저주 박치기';fx('afterimage',from.x,from.y,u.color,.1,{tx:u.x,ty:u.y,type:u.type,ownerId:u.id});}if(a.landed||a.t>=a.profile.active){a.phase='recovery';a.t=0;for(const s of meleeStrikes)if(s.source===u&&s.serial===a.serial)s.life=0;}}
else if(a.phase==='recovery'){u.vx=u.vy=0;if(a.t<a.profile.recovery)return;u.attack=null;u.ai.disengageUntil=elapsed+random(.2,.5);u.action='박치기 후 방황';}}
function advanceDolphinUltimate(u,a,dt){if(!a.multiStarted){a.multiStarted=true;a.origin={x:u.x,y:u.y};a.targets=alive().filter(v=>v.faction!==u.faction&&canPerceive(u,v)&&dist(u,v)<=300*unitScale(u)).sort((x,y)=>dist(u,x)-dist(u,y)).map(v=>v.id);a.next=0;fx('curseField',u.x,u.y,u.color,Math.max(1.5,a.targets.length*.65),{r:300*unitScale(u)});}if(u.attack)return false;while(a.next<a.targets.length){const targetId=a.targets[a.next++],target=units.find(v=>v.id===targetId&&v.hp>0&&canPerceive(u,v));if(target&&startHeadbutt(u,target,true))return false;}return true;}
function launchGreatImpact(u,a){spawnMeleeStrike(u,{...a,serial:++u.attackSerial,profile:{reach:190,cone:.7,active:.25,impulse:500},hiddenLaunch:false},u.dmg*1.5,true);projectiles.push({x:u.x+Math.cos(a.angle)*48,y:u.y+Math.sin(a.angle)*48,vx:Math.cos(a.angle)*640,vy:Math.sin(a.angle)*640,source:u,color:'#e5d3ae',damage:u.dmg*2.7,power:u.dmg*2.7,life:1.5,type:u.type,ultimate:'greatImpact',radius:48*unitScale(u),visualScale:unitScale(u),impulse:540,hitIds:new Set(),trail:[],bouncesRemaining:0,homing:false,guaranteed:false,hiddenLaunch:false});}
function renderGreatSwordWeapon(u,a,p){if(u.lostSword)return;let angle=0;if(u.guardRemaining>0)angle=-1.25;else if(u.ultCast)angle=-1.55-clamp(u.ultCast.t/u.ultCast.duration,0,1)*.8;else if(a)angle=a.phase==='windup'?-p*2:a.phase==='active'?-2+p*3.4:1.4*(1-p);ctx.save();ctx.rotate(angle);ctx.translate(20,15);const boost=a?.sizeBoost??1;ctx.scale(boost,boost);sword(155,31,'#e6dfca');ctx.fillStyle='#8e785e';ctx.fillRect(38,-11,76,5);ctx.restore();}
function renderNovelObjects(){for(const u of alive()){if(u.type===10&&u.lostSword){const s=u.lostSword;ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.rotation);ctx.scale(s.scale*s.sizeBoost,s.scale*s.sizeBoost);ctx.globalAlpha*=.9;sword(155,31,'#e6dfca');ctx.restore();if(s.flight<=0){for(let i=0;i<4;i++)texel(s.x-6+i*4,s.y+12,3,u.color,.6);}}if(novelLocked(u)){const r=44*unitScale(u);slashStroke(u.x,u.y,r,u.face-1.45,u.face+1.45,'#e6d7b7',12,.75);for(let i=0;i<8;i++)texel(u.x-20+i*5,u.y-65,3,i<u.guardRemaining*2?'#e6d7b7':'#475040',.8);}if(u.curseTime>0){const r=35*unitScale(u);for(let i=0;i<4;i++){const a=elapsed*2+i*Math.PI/2;texel(u.x+Math.cos(a)*r,u.y+Math.sin(a)*r,3,'#acf0ff',.65);}}}}
function renderCurseEffect(e,p,alpha){const u=e.unitId?units.find(v=>v.id===e.unitId):null,x=u?.x??e.x,y=u?.y??e.y;if(e.kind==='curseField'){circle(x,y,e.r,'#9edfec',false,3);for(let i=0;i<8;i++){const a=i*Math.PI/4+p*.8;slashStroke(x,y,e.r*.94,a,a+.35,'#80c9dd',5,alpha*.35);}return;}const r=(e.r??60)*(1-p*.7);slashStroke(x,y,r,-p*4,-p*4+Math.PI*1.65,'#b6e8f1',6,alpha);}
function renderGreatImpact(p){const a=Math.atan2(p.vy,p.vx);bladeStreak(p.x,p.y,a,150,75,'#c9b68f',.5);bladeStreak(p.x,p.y,a,105,36,'#fff2cd',.9);for(let i=0;i<5;i++){const back=i*24;const x=p.x-Math.cos(a)*back,y=p.y-Math.sin(a)*back;bladeStreak(x,y,a+(i%2?1:-1)*.85,35,8,'#e5d3ae',.7-i*.1);}}

// Predator bites use an actual frontal volume and share ordinary physical clashes.
function releasePredatorBite(u,a,ultimate=false){const profile=ultimate?{...ATTACK_PROFILES[12],reach:175,active:.5,cone:1.15,impulse:350}:a.profile;if(!ultimate){a.biteDashRemaining=48*Math.min(1.5,unitScale(u));u.headingX=u.headingY=u.vx=u.vy=0;}const s=spawnMeleeStrike(u,{...a,profile,serial:ultimate?++u.attackSerial:a.serial,hiddenLaunch:false},u.dmg*(ultimate?1.8:1),ultimate);s.bite=true;s.maxTargets=3;s.executeThreshold=ultimate?.2:.13;fx('bite',u.x,u.y,u.color,.26,{angle:a.angle,r:s.reach,ultimate});burst(u.x+Math.cos(a.angle)*s.reach*.6,u.y+Math.sin(a.angle)*s.reach*.6,'#e6edc2',32,190,.85,a.angle);impactPause(ultimate?2.8:1.7,a.angle);}
function advancePredatorBiteDash(u,a,dt){if(u.type!==12||a.phase!=='active'||!(a.biteDashRemaining>0)||dt<=0)return;const before={x:u.x,y:u.y},move=Math.min(a.biteDashRemaining,400*Math.min(1.5,unitScale(u))*dt);u.x=clamp(u.x+Math.cos(a.angle)*move,28,772);u.y=clamp(u.y+Math.sin(a.angle)*move,28,772);const traveled=dist(before,u);a.biteDashRemaining=traveled<.01?0:Math.max(0,a.biteDashRemaining-traveled);u.vx=(u.x-before.x)/dt;u.vy=(u.y-before.y)/dt;u.face=a.angle;u.headingX=u.headingY=0;u.action='씹어먹기 · 전진';if(traveled>.01)fx('afterimage',before.x,before.y,u.color,.1,{tx:u.x,ty:u.y,type:u.type,ownerId:u.id});}
function onPredatorKill(source,target){if(source.type!==12||source.hp<=0)return;source.predatorStacks=(source.predatorStacks??0)+1;restoreCombatHp(source,source.maxHp*.1,source);fx('scales',source.x,source.y,source.color,.5,{unitId:source.id,r:45*unitScale(source)});fx('devour',target.x,target.y,source.color,.28,{tx:source.x,ty:source.y,r:55});burst(source.x,source.y,'#d9efaf',22,100,Math.PI*2,0,'mote');}
function renderPredatorJaw(u,a,p){const strike=meleeStrikes.find(s=>s.source===u&&s.bite&&s.ultimate&&strikeLive(s));if(!a&&strike){a={phase:'active'};p=clamp(strike.age/strike.duration,0,1);}const ult=u.ultCast,phase=ult?'windup':a?.phase??'idle',progress=ult?clamp(ult.t/ult.duration,0,1):p,opening=phase==='windup'?.1+progress*.7:phase==='active'?.75*(1-progress):phase==='recovery'?.12:.15,length=ult||strike?150:115;for(const side of [-1,1]){ctx.save();ctx.rotate(side*opening);ctx.fillStyle=ult?'#d4bf83':'#809357';ctx.strokeStyle='#dce5b5';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(20,side*8);ctx.lineTo(length,side*12);ctx.lineTo(length+12,side*4);ctx.lineTo(30,side*-3);ctx.closePath();ctx.fill();ctx.stroke();for(let i=0;i<6;i++){const x=37+i*(length-40)/6;ctx.beginPath();ctx.moveTo(x,side*0);ctx.lineTo(x+6,side*-13);ctx.lineTo(x+11,side*0);ctx.closePath();ctx.fillStyle='#fff1ce';ctx.fill();texel(x,side*11,4,'#465538',.8);}ctx.restore();}}
function renderBiteStrike(s){const p=clamp(s.age/s.duration,0,1),x=s.source.x+Math.cos(s.angle)*s.reach*.6,y=s.source.y+Math.sin(s.angle)*s.reach*.6;bladeStreak(x,y,s.angle+Math.PI/2,s.reach*.85,20*(s.visualScale??1),'#fff2ca',1-p);for(const side of [-1,1])bladeStreak(x+Math.cos(s.angle+side*.9)*s.reach*.2,y+Math.sin(s.angle+side*.9)*s.reach*.2,s.angle+side*.9,55*(s.visualScale??1),10*(s.visualScale??1),s.color,(1-p)*.8);}
function renderPredatorEffect(e,p,alpha){if(e.kind==='devour'){for(let i=0;i<8;i++){const a=i*Math.PI/4,r=e.r*(1-p),x=e.x+(e.tx-e.x)*p+Math.cos(a)*r,y=e.y+(e.ty-e.y)*p+Math.sin(a)*r;bladeStreak(x,y,Math.atan2(e.ty-y,e.tx-x),24,6,e.color,alpha);}return;}if(e.kind==='scales'){const u=units.find(u=>u.id===e.unitId),x=u?.x??e.x,y=u?.y??e.y;for(let i=0;i<8;i++){const a=i*Math.PI/4,r=e.r*(1+p*.25);texel(x+Math.cos(a)*r,y+Math.sin(a)*r,5,e.color,alpha);}return;}const x=e.x+Math.cos(e.angle)*e.r*.65,y=e.y+Math.sin(e.angle)*e.r*.65;bladeStreak(x,y,e.angle+Math.PI/2,e.r*.8,16,e.ultimate?'#ffe4a9':'#d3e7b5',alpha);}

// A thrown bomb follows a fixed arc, lands, and remains a clashable physical object.
function throwBomb(u,a,ultimate=false){const scale=unitScale(u),target=units.find(v=>v.id===a.targetId&&v.hp>0&&canPerceive(u,v)),distance=clamp(a.throwDistance??(a.point?dist(u,a.point):target?dist(u,target):280),90,ultimate?480:430)*scale,angle=a.angle+random(-.04,.04),point={x:clamp(u.x+Math.cos(angle)*distance,25,775),y:clamp(u.y+Math.sin(angle)*distance,25,775)},flight=ultimate?.7:.55,x=clamp(u.x+Math.cos(angle)*32*scale,25,775),y=clamp(u.y+Math.sin(angle)*32*scale,25,775),damage=u.dmg*(ultimate?2.6:1),fuse=ultimate?2.5:2;const bomb={x,y,vx:(point.x-x)/flight,vy:(point.y-y)/flight,source:u,type:13,kind:'bomb',color:ultimate?'#ffd187':'#e9a05f',damage,power:damage,radius:(ultimate?24:13)*scale,blastRadius:(ultimate?210:120)*scale,visualScale:scale,flight,maxFlight:flight,fuse,maxFuse:fuse,life:fuse+.02,trail:[],bouncesRemaining:0,ultimate:ultimate?'kingBomb':false,impulse:ultimate?480:290,hiddenLaunch:a.hiddenLaunch??isConcealed(u),homing:false,guaranteed:false};projectiles.push(bomb);u.kx-=Math.cos(angle)*45;u.ky-=Math.sin(angle)*45;burst(x,y,'#ffd796',14,150,.7,angle);return bomb;}
function detonateBomb(bomb){if(bomb.detonated||bomb.life<=0)return;bomb.detonated=true;bomb.life=0;const point={x:bomb.x,y:bomb.y},radius=bomb.blastRadius;let lastVictim=null;fx('bombBlast',point.x,point.y,bomb.color,.48,{r:radius,large:!!bomb.ultimate});for(let i=0;i<14;i++){const a=i*Math.PI*2/14;burst(point.x,point.y,i%3?'#e9a05f':'#fff0c0',8,bomb.ultimate?440:320,.16,a,'debris');}impactPause(bomb.ultimate?3.1:2.2,0);for(const target of alive()){if(target.faction===bomb.source.faction||dist(point,target)>radius+24*unitScale(target))continue;const angle=Math.atan2(target.y-point.y,target.x-point.x);attackHit(target,bomb.damage,bomb.source,{angle,impulse:bomb.impulse,attackToken:bomb,attackOrigin:point,hiddenLaunch:bomb.hiddenLaunch,visibleHazard:true});if(target.hp<=0)lastVictim=target;}return lastVictim;}
function advanceBomber(u,enemies,dt){if(u.type!==13||u.hp<=0)return false;if(u.stun>0){u.vx=u.vy=u.headingX=u.headingY=0;u.action='기절';return true;}if(u.hp<=u.maxHp*.2)u.bomberRush=true;if(!u.bomberRush)return false;u.attack=null;u.ultCast=null;u.dodgeState=null;u.evadeTime=0;u.bomberRushTime+=dt;const target=enemies.slice().sort((a,b)=>dist(u,a)-dist(u,b))[0];if(u.bomberFuse==null){if(target)u.face=Math.atan2(target.y-u.y,target.x-u.x);if(target&&dist(u,target)<=78*unitScale(u)||u.bomberRushTime>=3.5){u.bomberFuse=.6;u.vx=u.vy=u.kx=u.ky=0;u.action='자폭 점화';}else if(target){const angle=Math.atan2(target.y-u.y,target.x-u.x);steerArchetype(u,Math.cos(angle),Math.sin(angle),dt,1.8*movementRate(u));u.action='최후의 돌진';}return true;}u.vx=u.vy=u.kx=u.ky=0;u.bomberFuse-=dt;u.action='자폭 점화';if(u.bomberFuse<=0){const source=units.find(v=>v.id===u.lastDamageSourceId&&v.faction!==u.faction);if(source)finalHitConfirmed(u,source);u.hp=0;eliminateUnit(u,source,u.face,{wave:false});const lastVictim=detonateBomb({x:u.x,y:u.y,source:u,damage:u.dmg*2.5,blastRadius:165*unitScale(u),color:'#ffb871',impulse:520,life:1,ultimate:'selfDestruct',hiddenLaunch:false});if(lastVictim&&new Set(alive().map(v=>v.faction)).size<=1)finalHitConfirmed(lastVictim,u,true);addLog(`${u.name} · 최후의 자폭`);}return true;}
// Recognizing a burning fuse is probabilistic, and never grants automatic immunity.
function moveBombEscape(u,dt){if(u.attack||u.ultCast||u.shadowTime>0||u.combatStance==='cover')return false;const threat=projectiles.filter(p=>p.kind==='bomb'&&p.life>0&&p.source.faction!==u.faction&&!p.hiddenLaunch&&inAttackView(u,p)&&p.fuse<.8&&dist(u,p)<p.blastRadius+30).sort((a,b)=>a.fuse-b.fuse)[0];if(!threat)return false;let notice=u.ai.perception.get(threat);if(!notice){notice={roll:Math.random()};u.ai.perception.set(threat,notice);}if(notice.roll>(u.combatStance==='cautious'?.8:u.combatStance==='rush'?.35:.62))return false;const angle=dist(u,threat)<1?u.face+Math.PI:Math.atan2(u.y-threat.y,u.x-threat.x);steerArchetype(u,Math.cos(angle),Math.sin(angle),dt,movementRate(u));u.action='도화선 확인 · 폭발 범위 이탈';return true;}
function renderBombGroundTelegraphs(){for(const p of projectiles){if(p.kind!=='bomb'||p.life<=0||p.flight>0)continue;const pulse=.5+.5*Math.sin(elapsed*(p.fuse<.6?22:8));ctx.save();circle(p.x,p.y,p.blastRadius,'#dd76451b');circle(p.x,p.y,p.blastRadius,'#db9556',false,2);slashStroke(p.x,p.y,p.blastRadius,-Math.PI/2,-Math.PI/2+Math.PI*2*clamp(1-p.fuse/p.maxFuse,0,1),'#ffcc8e',5,.4+pulse*.25);ctx.restore();}}
function renderBombProjectile(p){const progress=clamp(1-p.flight/p.maxFlight,0,1),height=p.flight>0?Math.sin(progress*Math.PI)*(p.ultimate?95:65):0,size=p.ultimate?55:33;circle(p.x,p.y+5,p.ultimate?22:13,'#0006');renderEmoji(13,p.x,p.y-height,size);const sparkY=p.y-height-size*.45,sparkX=p.x+size*.22;pixelSprite(sparkX,sparkY,'#ffd38b',p.ultimate?1.2:.8,'ember',.7+.3*Math.sin(elapsed*23));if(p.fuse<.55)hitGlyph(p.x,p.y-height,0,p.ultimate?20:12,'#ffb663',0,.15+.15*Math.sin(elapsed*22));}
function renderBombWeapon(u,a,p){const ult=u.ultCast,progress=ult?clamp(ult.t/ult.duration,0,1):p,phase=ult?'windup':a?.phase;ctx.save();ctx.rotate(phase==='windup'?-.3-progress*1.65:phase==='active'?-1.9+progress*2.9:.3);ctx.translate(29,12);ctx.fillStyle='#d5b28a';ctx.fillRect(-13,-4,22,8);if(phase!=='active'&&phase!=='recovery')renderEmoji(13,14,0,ult?53:29);if(u.bomberRush){ctx.restore();const spark=u.bomberFuse!=null?1-clamp(u.bomberFuse/.6,0,1):.15;slashStroke(0,0,38,-Math.PI/2,-Math.PI/2+Math.PI*2*spark,'#ffbc75',6,.8);pixelSprite(0,-35,'#ffe0a0',1,'ember');return;}ctx.restore();}
function renderBombBlast(e){const p=1-e.life/e.max,alpha=Math.pow(1-p,1.5),r=e.r;ctx.save();if(p<.26){const size=(e.large?3:2)*(1+p*2);pixelSprite(e.x,e.y,p<.1?'#fff0cd':'#f0aa69',size,'blast',alpha);bladeStreak(e.x,e.y,.7,r*.9,38,'#fff3d6',alpha);bladeStreak(e.x,e.y,-.9,r*.7,24,'#ffd091',alpha);}const wave=r*(1-Math.pow(1-p,3));circle(e.x,e.y,wave,'#ffc489',false,Math.max(2,13*(1-p)));circle(e.x,e.y,wave+5,'#fff0cc',false,Math.max(2,4*(1-p)));for(let i=0;i<5;i++){const a=i*2.4,d=r*.33*vfxNoise(i,e.x);pixelSprite(e.x+Math.cos(a)*d,e.y+Math.sin(a)*d-p*35,'#8a6450',1.3+p,'smoke',alpha*.25);}ctx.restore();}
